cd /app && python3 - <<'EOF'
import socket,time,re
s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM); s.connect("/tmp/qemu-monitor.sock"); time.sleep(0.3); s.recv(65536)
def cmd(c):
    s.sendall((c+"\n").encode()); time.sleep(0.3); return s.recv(65536).decode(errors="replace")
def reg():
    r=cmd("info registers")
    m=re.search(r"EIP=([0-9a-fA-F]+)",r); e=m.group(1) if m else "?"
    cs=re.search(r"CS =([0-9a-fA-F]+)",r); 
    return e, (cs.group(1) if cs else "?")
for i in range(6):
    print(reg()); time.sleep(1)
print("status", cmd("info status").strip().splitlines()[-1])
s.close()
EOF

